{"path":"outputs/t07_query.sparql","content":"PREFIX wd: <https://www.wikidata.org/entity/>
PREFIX wdt: <https://www.wikidata.org/prop/direct/>

SELECT ?item ?itemLabel ?coord
WHERE {
  # The item must have coordinates
  ?item wdt:P625 ?coord .
  # It must be located in the configured city (Alicante)
  ?item wdt:P1311 wd:Q11959 .
  # It must be an instance of one of the requested POI types
  ?item wdt:P31 ?type .
  VALUES ?type {
    wdt:Q18604  # art gallery
    wdt:Q18887  # library
    wdt:Q157617  # monument
    wdt:Q571125  # museum
    wdt:Q133456  # theatre building
  }
  # Get the English label of the item
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}"}

